<script lang="ts">
 import {onMount} from 'svelte';
 import {registerModelTools} from '$lib/model-tools';
 import type {createApartment} from '$lib/apartment';
 let host:HTMLDivElement;let api:Awaited<ReturnType<typeof createApartment>>|undefined;
 let layout='shell',floor='oak',light='day',furniture=false,depth=3.4,width=3.15;
 let ready=false,error='',hint='Loading the apartment…',mode='orbit';
 function update(){api?.update({layout,floor,light,furniture,depth,width});}
 function view(v:string){mode=v;api?.view(v);}
 onMount(()=>{let disposed=false;const unregister=registerModelTools(v=>{layout=v;update();});import('$lib/apartment').then(async m=>{const a=await m.createApartment(host,message=>hint=message);if(disposed){a.destroy();return;}api=a;ready=true;update();}).catch(e=>error=`The model could not load. ${e.message}`);return()=>{disposed=true;unregister();api?.destroy();};});
</script>
<svelte:head><title>Eureka · Apartment studio</title><meta name="description" content="Explore the southeast Eureka apartment and compare an open shell with a proposed two-bedroom layout."/></svelte:head>
<div class="app">
 <header><a href="/" class="brand"><span class="mark">E</span> EUREKA <span class="divider">/</span><span class="sub">Apartment studio</span></a><span class="badge">SOUTHEAST · FLOOR 4</span></header>
 <main>
  <aside>
   <div class="intro"><span class="eyebrow">YOUR NEXT HOME</span><h1>Room to imagine.</h1><p>Explore the shell. Try two bedrooms. Find your materials.</p></div>
   <fieldset disabled={!ready}><legend>01 <span>Layout</span></legend><div class="layouts">{#each [['shell','Open shell','Start with the space'],['bedrooms','Two bedrooms','First layout proposal'],['existing','Source model','Original interior elements']] as item}<button class:active={layout===item[0]} onclick={()=>{layout=item[0];update();}} aria-pressed={layout===item[0]}><span>{item[1]}<small>{item[2]}</small></span><span class="dot"></span></button>{/each}</div>
   {#if layout==='bedrooms'}<div class="dimensions"><label for="width">Bedroom width <output>{width.toFixed(2)} m</output></label><input id="width" type="range" min="2.7" max="3.5" step=".05" bind:value={width} oninput={update}/><label for="depth">Bedroom depth <output>{depth.toFixed(2)} m</output></label><input id="depth" type="range" min="2.8" max="4" step=".05" bind:value={depth} oninput={update}/></div>{/if}
   </fieldset>
   <fieldset disabled={!ready}><legend>02 <span>Finishes & atmosphere</span></legend><label for="floor">Floor finish</label><select id="floor" bind:value={floor} onchange={update}><option value="oak">Natural oak</option><option value="concrete">Soft concrete</option><option value="walnut">Dark walnut</option></select><div class="segmented">{#each [['day','Daylight'],['evening','Evening']] as i}<button class:chosen={light===i[0]} onclick={()=>{light=i[0];update();}} aria-pressed={light===i[0]}>{i[1]}</button>{/each}</div><label class="check"><input type="checkbox" bind:checked={furniture} onchange={update}/>Show sample furniture</label></fieldset>
   <div class="note"><strong>First-pass model</strong><p>Extracted from your SketchUp file. Apartment boundary and fixed services need checking against the drawings. Bedrooms and furniture are proposals. Lighting is illustrative; walking has no interior collision detection.</p></div>
   <button class="download" disabled={!ready} onclick={()=>api?.download().catch(e=>error=e.message)}>Download current 3D model <span>↗</span></button>
  </aside>
  <section class="workspace" aria-label="Interactive apartment model">
   <div class="canvas" bind:this={host}></div>
   <nav aria-label="Camera view">{#each [['orbit','3D overview'],['plan','Floor plan'],['walk','Walk inside']] as v}<button disabled={!ready} class:chosen={mode===v[0]} onclick={()=>view(v[0])}>{v[1]}</button>{/each}</nav>
   {#if !ready || error}<div class="loading" role="status">{error||'Preparing your apartment…'}</div>{/if}
   <div class="model-label"><span class="live"></span>{layout==='bedrooms'?'TWO-BEDROOM PROPOSAL':layout==='existing'?'SOURCE INTERIOR':'OPEN SHELL'}<small>Model units: metres</small></div>
   <div class="help">{hint}</div>
  </section>
 </main>
</div>
<style>
 :global(*){box-sizing:border-box} :global(body){margin:0;font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#20323c;background:#f6f8f9;font-size:16px} :global(button),:global(select),:global(input){font:inherit} :global(button){cursor:pointer} :global(button:disabled){opacity:.5;cursor:wait} :global(button:focus-visible),:global(select:focus-visible),:global(input:focus-visible){outline:3px solid #127c99;outline-offset:3px}header{height:78px;display:flex;justify-content:space-between;align-items:center;padding:0 32px;border-bottom:1px solid #dce2e6;background:white}.brand{display:flex;gap:14px;align-items:center;text-decoration:none;color:inherit;font-size:17px;font-weight:700;letter-spacing:.08em}.mark{background:#203f4e;color:white;display:grid;place-items:center;width:35px;height:35px;border-radius:9px}.divider{color:#c4cdd2;margin:0 8px;font-weight:400}.sub{font-size:15px;letter-spacing:0;font-weight:450}.badge{font-size:12px;letter-spacing:.12em;color:#657982}main{display:grid;grid-template-columns:320px 1fr;height:calc(100dvh - 78px);min-height:650px}aside{overflow:auto;background:white;padding:30px 26px;display:flex;flex-direction:column;gap:27px;border-right:1px solid #dce2e6}.eyebrow{font-size:12px;letter-spacing:.15em;color:#60808f;font-weight:650}h1{font-size:29px;line-height:1.15;letter-spacing:-.04em;font-weight:550;margin:10px 0 12px}p{font-size:14px;color:#687a83;line-height:1.55;margin:0}fieldset{border:0;padding:0;margin:0;min-width:0}legend{font-size:12px;color:#75909e;letter-spacing:.06em;margin-bottom:15px}legend span{font-size:15px;font-weight:600;color:#263e49;margin-left:9px;letter-spacing:0}.layouts{display:grid;gap:8px}.layouts button{background:white;border:1px solid #dce3e7;border-radius:9px;text-align:left;padding:12px 14px;display:flex;justify-content:space-between;align-items:center;color:#263e49;font-size:15px}.layouts button.active{background:#eff6f8;border-color:#3a788e}.layouts small{display:block;font-size:12px;color:#7185