.help{position:absolute;bottom:22px;left:28px;color:#556f7b;font-size:12px;background:#ffffffbd;border-radius:5px;padding:7px 10px}.loading{position:absolute;top:45%;left:50%;transform:translateX(-50%);background:white;padding:20px;border-radius:12px;box-shadow:0 5px 35px #0001;max-width:90%}@media(max-width:800px){header{padding:0 18px;height:64px}.sub,.divider,.badge{display:none}main{display:flex;flex-direction:column-reverse;height:auto;min-height:0}.workspace{height:65dvh;min-height:420px}aside{padding:24px;display:grid;gap:22px}.intro{display:none}nav{top:15px}nav button{padding:9px 12px}.model-label{left:15px;bottom:64px}.help{left:15px;right:15px;bottom:15px;font-size:12px}}
</style>
